// ExampleAPIClient - generated by API Free from 2 requests that worked in "Try it".
// Types come from one response each: widen int to double, or add ?, where the API can answer differently.
//
//   var client = new ExampleAPIClient(new HttpClient(), "your key");
//   var result = await client.DeleteUserAsync();

using System;
using System.Collections.Generic;
using System.Globalization;
using System.Net.Http;
using System.Net.Http.Json;
using System.Text;
using System.Text.Json;
using System.Text.Json.Serialization;
using System.Threading;
using System.Threading.Tasks;

public sealed class ExampleAPIClient
{
    private readonly HttpClient _http;
    private readonly string _apiKey;

    public ExampleAPIClient(HttpClient http, string apiKey)
    {
        _http = http;
        _apiKey = apiKey;
    }

    /// <summary>DELETE https://api.example.com/v1/users/2</summary>
    public async Task DeleteUserAsync(int userId = 2, CancellationToken ct = default)
    {
        var url = $"https://api.example.com/v1/users/{userId}";
        using var request = new HttpRequestMessage(HttpMethod.Delete, url);
        using var response = await _http.SendAsync(request, ct);
        response.EnsureSuccessStatusCode();
    }

    /// <summary>PUT https://api.example.com/v1/items/9999999999/tags?force=true&amp;ratio=0.50&amp;zip=01234&amp;neg=-3</summary>
    /// <remarks>Tested with this body: a=b&amp;c=d</remarks>
    public async Task<PutTagsResponse?> PutTagsAsync(string body, long itemId = 9999999999, string force = "true", double ratio = 0.50, string zip = "01234", int neg = -3, CancellationToken ct = default)
    {
        var url = $"https://api.example.com/v1/items/{itemId}/tags?force={Uri.EscapeDataString(force)}&ratio={ratio.ToString(CultureInfo.InvariantCulture)}&zip={Uri.EscapeDataString(zip)}&neg={neg}";
        using var request = new HttpRequestMessage(HttpMethod.Put, url);
        request.Headers.TryAddWithoutValidation("X-Api-Key", _apiKey);
        request.Content = new StringContent(body, Encoding.UTF8, "application/x-www-form-urlencoded");
        using var response = await _http.SendAsync(request, ct);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadFromJsonAsync<PutTagsResponse>(ct);
    }
}

public sealed class PutTagsResponse
{
    [JsonPropertyName("ok")]
    public bool Ok { get; set; }
    [JsonPropertyName("count")]
    public int Count { get; set; }
    [JsonPropertyName("ratio")]
    public double Ratio { get; set; }
    [JsonPropertyName("when")]
    public DateTimeOffset When { get; set; }
    [JsonPropertyName("list")]
    public List<ListItem> List { get; set; } = [];
}

public sealed class ListItem
{
    [JsonPropertyName("a")]
    public int A { get; set; }
    [JsonPropertyName("b")]
    public object? B { get; set; }
}